JOJO_STANDS_FULL_DB: list[dict[str, Any]] = [
    {
        "id": f"stand_{idx + 1}",
        "name": name,
        "part_num": pnum,
        "part": ptitle,
        "user": user,
        "stand_type": stype,
        "stats": f"Сила {st.split('|')[0]} | Скор. {st.split('|')[1]} | Дальн. {st.split('|')[2]} | Выносл. {st.split('|')[3]} | Точн. {st.split('|')[4]} | Потенц. {st.split('|')[5]}",
        "stats_raw": st,
        "ability": ability,
    }
    for idx, (name, pnum, ptitle, user, stype, st, ability) in enumerate(_RAW_JOJO_STANDS)
]


def search_jojo_stands_all(query: str = "", part_num: int = 0, stand_type: str = "") -> dict[str, Any]:
    q = (query or "").strip().lower()
    st_f = (stand_type or "").strip().lower()
    items = [
        s
        for s in JOJO_STANDS_FULL_DB
        if (part_num == 0 or s["part_num"] == part_num)
        and (not st_f or st_f in s["stand_type"].lower())
        and (
            not q
            or q in s["name"].lower()
            or q in s["user"].lower()
            or q in s["part"].lower()
            or q in s["ability"].lower()
            or q in s["stand_type"].lower()
        )
    ]
    part_counts = {
        p: sum(1 for x in JOJO_STANDS_FULL_DB if x["part_num"] == p)
        for p in (3, 4, 5, 6, 7, 8, 9)
    }
    return {
        "total_catalog": len(JOJO_STANDS_FULL_DB),
        "matched": len(items),
        "part_counts": part_counts,
        "items": items,
    }


def awaken_personal_stand(username: str = "") -> dict[str, Any]:
    seed_str = (username or "").strip()
    if seed_str:
        idx = int(hashlib.sha256(seed_str.lower().encode("utf-8")).hexdigest()[:8], 16) % len(JOJO_STANDS_FULL_DB)
        chosen = JOJO_STANDS_FULL_DB[idx]
    else:
        chosen = random.choice(JOJO_STANDS_FULL_DB)
    return {"stand": chosen, "deterministic": bool(seed_str)}


