ADULT_ACTRESSES_DB: list[dict[str, Any]] = []
for _idx, (
    _name,
    _country,
    _flag,
    _byear,
    _h,
    _w,
    _b_in,
    _wa_in,
    _hi_in,
    _cup,
    _enh,
    _hair,
    _eyes,
    _active,
    _awards,
) in enumerate(_RAW_ACTRESSES_18):
    _b_cm = round(_b_in * 2.54)
    _wa_cm = round(_wa_in * 2.54)
    _hi_cm = round(_hi_in * 2.54)
    _bmi = round(_w / ((_h / 100.0) ** 2), 1)
    _whr = round(_wa_cm / max(1, _hi_cm), 2)
    ADULT_ACTRESSES_DB.append(
        {
            "id": f"act18_{_idx + 1}",
            "name": _name,
            "country": _country,
            "flag": _flag,
            "birth_year": _byear,
            "age_2026": 2026 - _byear,
            "height_cm": _h,
            "weight_kg": _w,
            "bmi": _bmi,
            "waist_hip_ratio": _whr,
            "measurements_cm": f"{_b_cm}–{_wa_cm}–{_hi_cm} см",
            "measurements_in": f'{_b_in}"–{_wa_in}"–{_hi_in}"',
            "bust_cm": _b_cm,
            "waist_cm": _wa_cm,
            "hips_cm": _hi_cm,
            "cup": _cup,
            "breast_type": "Импланты (Enhanced)" if _enh else "Натуральная (Natural)",
            "natural": not _enh,
            "hair": _hair,
            "eyes": _eyes,
            "active_years": _active,
            "awards": _awards,
        }
    )


def search_adult_actresses(
    query: str = "",
    hair: str = "",
    cup: str = "",
    natural_only: bool = False,
    min_height: int = 140,
    max_height: int = 195,
    country: str = "",
) -> dict[str, Any]:
    q = (query or "").strip().lower()
    h_f = (hair or "").strip().lower()
    c_f = (cup or "").strip().upper()
    cnt_f = (country or "").strip().lower()

    matched = [
        a
        for a in ADULT_ACTRESSES_DB
        if min_height <= a["height_cm"] <= max_height
        and (not natural_only or a["natural"])
        and (not h_f or h_f in a["hair"].lower())
        and (not c_f or a["cup"].upper().startswith(c_f))
        and (not cnt_f or cnt_f in a["country"].lower())
        and (
            not q
            or q in a["name"].lower()
            or q in a["country"].lower()
            or q in a["hair"].lower()
            or q in a["eyes"].lower()
            or q in a["awards"].lower()
            or q in a["measurements_cm"].lower()
        )
    ]
    return {
        "total_catalog": len(ADULT_ACTRESSES_DB),
        "matched": len(matched),
        "items": matched,
    }


