HENTAI_TAGS_DICT: list[dict[str, Any]] = [
    {
        "id": f"htag_{idx + 1}",
        "tag_en": en,
        "jp_romaji": jp,
        "title_ru": ru,
        "category": cat,
        "tier": tier,
        "definition": defn,
    }
    for idx, (en, jp, ru, cat, tier, defn) in enumerate(_RAW_HENTAI_TAGS)
]


def search_hentai_tags(query: str = "", category: str = "", tier: str = "") -> dict[str, Any]:
    q = (query or "").strip().lower()
    cat_f = (category or "").strip().lower()
    tier_f = (tier or "").strip().lower()
    items = [
        t
        for t in HENTAI_TAGS_DICT
        if (not cat_f or cat_f == "all" or cat_f in t["category"].lower())
        and (not tier_f or tier_f == "all" or t["tier"].lower() == tier_f)
        and (
            not q
            or q in t["tag_en"].lower()
            or q in t["jp_romaji"].lower()
            or q in t["title_ru"].lower()
            or q in t["definition"].lower()
            or q in t["category"].lower()
        )
    ]
    categories = sorted({t["category"] for t in HENTAI_TAGS_DICT})
    return {
        "total_catalog": len(HENTAI_TAGS_DICT),
        "matched": len(items),
        "categories": categories,
        "items": items,
    }
